#!/usr/bin/env ruby
# frozen_string_literal: true
require 'json';require 'fileutils';require 'time'
root=File.expand_path('..',__dir__);identity=File.read(File.join(root,'server/GameCommon/src/main/java/com/aoo/bcg/common/event/RoomEventIdentity.java'),encoding:'UTF-8');outbox=File.read(File.join(root,'server/GameCommon/src/main/java/com/aoo/bcg/common/event/OutboxEvent.java'),encoding:'UTF-8');registry=File.read(File.join(root,'server/GameCommon/src/main/java/com/aoo/bcg/common/event/EventSchemaRegistry.java'),encoding:'UTF-8');journal=File.read(File.join(root,'server/GameCommon/src/main/java/com/aoo/bcg/common/event/JdbcRoomEventJournal.java'),encoding:'UTF-8');consumer=File.read(File.join(root,'server/GameCommon/src/main/java/com/aoo/bcg/common/event/RocketMqOutboxConsumer.java'),encoding:'UTF-8');matrix=JSON.parse(File.read(File.join(root,'docs/event-schema-evolution.json'),encoding:'UTF-8'))
checks={roomVersion:identity.include?('schemaVersion'),outboxVersion:outbox.include?('schemaVersion'),futureFailClosed:registry.include?('unsupported future event schema'),adjacentUpcast:registry.include?('missing adjacent event upcaster'),replayUsesRegistry:journal.include?('schemas.upcast'),consumerUsesRegistry:consumer.include?('schemas.requireSupported'),producerPolicy:matrix.dig('policy','producer')!=nil,consumerPolicy:matrix.dig('policy','consumer')!=nil,replayPolicy:matrix.dig('policy','replay')!=nil,families:Array(matrix['eventFamilies']).length>=4}
report={generatedAt:Time.now.utc.iso8601,checks:checks,passed:checks.values.all?};output=File.join(root,'work/audit/event-schema-evolution.json');FileUtils.mkdir_p(File.dirname(output));File.write(output,JSON.pretty_generate(report)+"\n");puts JSON.generate(checks:checks.length,passedChecks:checks.values.count(true),passed:report[:passed]);exit(report[:passed] ? 0 : 1)
